#include <iostream>
#include <vector>
#include <string>
#include <unordered_set>
#include <algorithm>

using namespace std;

bool isValidSudoku(vector<vector<char>>& board) {
    int rows[9][9] = {0}, cols[9][9] = {0}, boxes[9][9] = {0};
    for (int r = 0; r < 9; ++r) {
        for (int c = 0; c < 9; ++c) {
            if (board[r][c] == '.') continue;
            int num = board[r][c] - '1';
            int b = (r / 3) * 3 + (c / 3);
            if (rows[r][num] || cols[c][num] || boxes[b][num]) return false;
            rows[r][num] = cols[c][num] = boxes[b][num] = 1;
        }
    }
    return true;
}

int main() {
    char c;
    vector<vector<char>> board(9, vector<char>(9));
    int r = 0, col = 0;
    while (cin >> c) {
        if (c == '"') {
            cin >> c;
            board[r][col] = c;
            cin >> c; // closing quote
            col++;
            if (col == 9) { col = 0; r++; }
            if (r == 9) break;
        }
    }
    if (isValidSudoku(board)) cout << "true" << endl;
    else cout << "false" << endl;
    return 0;
}

